<form method="get" class="card p-4 mb-4 grid sm:grid-cols-2 lg:grid-cols-7 gap-2 items-end">
  <div class="lg:col-span-2"><label class="label">Search</label><input class="input" name="q" value="<?= e($f['q']) ?>" placeholder="Reference, name or mobile"></div>
  <div><label class="label">Status</label><select class="select" name="status"><option value="">All</option><?php foreach (order_statuses() as $k => $l): ?><option value="<?= $k ?>" <?= $f['st'] === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
  <div><label class="label">Source</label><select class="select" name="source"><option value="">All sources</option><?php foreach (['cart' => 'Cart', 'quick_order' => 'Quick Order', 'voice_order' => 'Voice Order'] as $k => $l): ?><option value="<?= $k ?>" <?= $f['src'] === $k ? 'selected' : '' ?>><?= $l ?></option><?php endforeach; ?></select></div>
  <div><label class="label">From</label><input type="date" class="input" name="from" value="<?= e($f['from']) ?>"></div><div><label class="label">To</label><input type="date" class="input" name="to" value="<?= e($f['to']) ?>"></div>
  <div class="flex gap-2"><button class="btn btn-primary flex-1">Filter</button><a class="btn btn-outline" href="<?= e(url('/admin/orders')) ?>">Reset</a></div></form>
<div class="flex justify-between items-center mb-3"><p class="text-sm muted"><?= (int)$total ?> order<?= $total == 1 ? '' : 's' ?></p><a class="btn btn-soft btn-sm" href="<?= e(url('/admin/orders/export?' . http_build_query(['q' => $f['q'], 'status' => $f['st'], 'source' => $f['src'], 'from' => $f['from'], 'to' => $f['to']]))) ?>"><?= icon('download', 'w-4 h-4') ?> Export CSV</a></div>
<div class="card overflow-hidden"><div class="overflow-x-auto"><table class="table-x w-full text-sm"><thead><tr><th>Reference</th><th>Date</th><th>Customer</th><th>Source</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody>
<?php foreach ($rows as $o): $srcCls = ['cart' => 'bg-gray-100 text-gray-700', 'quick_order' => 'bg-blue-100 text-blue-700', 'voice_order' => 'bg-purple-100 text-purple-700'][$o['order_source']]; ?>
<tr><td><a class="font-mono font-semibold text-primary" href="<?= e(url('/admin/orders/' . $o['id'])) ?>"><?= e($o['reference']) ?></a></td><td class="whitespace-nowrap text-xs"><?= e(date('d M Y, h:i A', strtotime($o['created_at']))) ?></td><td><b><?= e($o['customer_name']) ?></b><div class="text-xs muted"><?= e($o['mobile']) ?> · <?= e($o['city']) ?></div></td>
<td><span class="badge <?= $srcCls ?>"><?= e(ucwords(str_replace('_', ' ', $o['order_source']))) ?></span></td><td><?= (int)$o['items'] ?></td><td><b><?= money($o['total']) ?></b></td><td><span class="badge <?= $o['payment_status'] === 'paid' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-800' ?>"><?= e($o['payment_status']) ?></span></td><td><?= status_badge($o['status']) ?></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="8" class="text-center muted py-12">No orders match.</td></tr><?php endif; ?></tbody></table></div></div>
